import fs from 'node:fs';import crypto from 'node:crypto';import {createRequire} from 'node:module';import {loadSelectedAssets} from '../assets.mjs';
export const {createCanvas,loadImage,ImageData}=createRequire(import.meta.url)('@napi-rs/canvas'),root=new URL('../',import.meta.url),read=n=>JSON.parse(fs.readFileSync(new URL(n,root))),c=read('contract.json');
const sha=async b=>crypto.createHash('sha256').update(b).digest('hex'),bytes=async(url,pin)=>{const b=fs.readFileSync(url);if(await sha(b)!==pin)throw Error('PIN '+url);return b.buffer.slice(b.byteOffset,b.byteOffset+b.byteLength)},image=async(url,pin)=>loadImage(Buffer.from(await bytes(url,pin))),rgba=im=>{const cv=createCanvas(im.width,im.height),g=cv.getContext('2d');g.drawImage(im,0,0);return g.getImageData(0,0,im.width,im.height).data};
export const A=await loadSelectedAssets({contract:c,rootURL:root,bytes,image,rgba,makeCanvas:createCanvas,sha}),assets={};for(const[k,s]of Object.entries(c.sources))assets[k]=k==='exterior'?A.source:await image(new URL(s.path,root),s.sha256);A.actors.forEach((actor,i)=>assets['actor:'+i]=actor);
